//! Pane updates itself from GitHub releases, the way `install.sh` installed
//! it: a release's archive, verified against the release's own
//! `SHA256SUMS`, unpacked into a **fresh** `<root>/versions/<tag>`, the
//! subscription broker the release pins adopted, and `<root>/current`
//! repointed -- never a byte written over a binary that may be running. The
//! running session keeps its binary; the next start runs the new one, and
//! the person is told so once: *Pane <tag> installed · restart to update*.
//!
//! **Only a release install updates itself.** The install is read from the
//! running binary's own path (`<root>/versions/<tag>/bin/pane`); a binary
//! run from a build tree, or a version directory whose name is not exactly a
//! release tag (a developer's `v0.1.0-pre.1-1316-gf96f87f0`), is left alone
//! -- `pane update` says why rather than guess what it is newer than.

use std::fs;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{Duration, SystemTime};

use sha2::Digest as _;

/// The repository releases are published from.
pub const REPOSITORY: &str = "HarzerHeribert/glasshouse";
/// Set to anything to stop the background check (`pane update` still works).
pub const DISABLE_ENV: &str = "PANE_DISABLE_AUTOUPDATE";
/// How often the background check may ask GitHub at all.
const CHECK_EVERY: Duration = Duration::from_secs(24 * 60 * 60);
/// The stamp the background check leaves in the install root.
const STAMP: &str = "update-check";
/// What the adopted broker's pin was, in the install root.
const BROKER_STAMP: &str = "broker-version";
const TIMEOUT: Duration = Duration::from_secs(120);

/// The notice the background check leaves for the session to show once.
static NOTICE: Mutex<Option<String>> = Mutex::new(None);

/// A release install: the root holding `versions/` and `current`, and the
/// tag of the version directory the running binary lives in.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Install {
    pub root: PathBuf,
    pub tag: String,
}

impl Install {
    /// The install the running binary belongs to, or `None` when it runs
    /// from anywhere else.
    #[must_use]
    pub fn of_running() -> Option<Self> {
        let exe = std::env::current_exe().ok()?.canonicalize().ok()?;
        Self::from_exe(&exe)
    }

    /// `<root>/versions/<tag>/bin/<pane>` read backwards; `None` for any
    /// other shape.
    #[must_use]
    pub fn from_exe(exe: &Path) -> Option<Self> {
        let bin = exe.parent()?;
        let version = bin.parent()?;
        let versions = version.parent()?;
        if bin.file_name()? != "bin" || versions.file_name()? != "versions" {
            return None;
        }
        Some(Self {
            root: versions.parent()?.to_path_buf(),
            tag: version.file_name()?.to_str()?.to_string(),
        })
    }

    /// Whether this install's directory is exactly a release tag.
    #[must_use]
    pub fn is_release(&self) -> bool {
        parse_tag(&self.tag).is_some()
    }

    /// The tag `<root>/current` points at, when it points at a version.
    #[must_use]
    pub fn current_tag(&self) -> Option<String> {
        let target = fs::read_link(self.root.join("current")).ok()?;
        Some(target.file_name()?.to_str()?.to_string())
    }
}

/// `v<major>.<minor>.<patch>` with an optional `-pre.<n>`, and nothing else.
#[must_use]
pub fn parse_tag(tag: &str) -> Option<(u64, u64, u64, Option<u64>)> {
    let rest = tag.strip_prefix('v')?;
    let (core, pre) = match rest.split_once("-pre.") {
        Some((core, pre)) => (core, Some(pre.parse().ok()?)),
        None => (rest, None),
    };
    let mut parts = core.split('.');
    let version = (
        parts.next()?.parse().ok()?,
        parts.next()?.parse().ok()?,
        parts.next()?.parse().ok()?,
    );
    parts
        .next()
        .is_none()
        .then_some((version.0, version.1, version.2, pre))
}

/// Whether `candidate` is a later release than `than`. A release without a
/// pre-release number is later than every pre-release of the same version.
#[must_use]
pub fn newer(candidate: &str, than: &str) -> bool {
    let (Some(a), Some(b)) = (parse_tag(candidate), parse_tag(than)) else {
        return false;
    };
    let rank = |(major, minor, patch, pre): (u64, u64, u64, Option<u64>)| {
        (major, minor, patch, pre.map_or((1, 0), |n| (0, n)))
    };
    rank(a) > rank(b)
}

/// This build's release target, as the release archives name it.
#[must_use]
pub fn target() -> Option<&'static str> {
    match (std::env::consts::OS, std::env::consts::ARCH) {
        ("macos", "aarch64") => Some("aarch64-apple-darwin"),
        ("linux", "x86_64") => Some("x86_64-unknown-linux-gnu"),
        ("linux", "aarch64") => Some("aarch64-unknown-linux-gnu"),
        ("windows", "x86_64") => Some("x86_64-pc-windows-msvc"),
        ("windows", "aarch64") => Some("aarch64-pc-windows-msvc"),
        _ => None,
    }
}

/// Where releases are listed and downloaded from; each overridable for a
/// test, exactly as `install.sh`'s are.
#[derive(Debug, Clone)]
pub struct Source {
    pub releases_api: String,
    pub downloads: String,
    pub broker_downloads: Option<String>,
}

impl Source {
    #[must_use]
    pub fn from_env() -> Self {
        let var = |name: &str| std::env::var(name).ok().filter(|v| !v.is_empty());
        Self {
            releases_api: var("PANE_UPDATE_API").unwrap_or_else(|| {
                format!("https://api.github.com/repos/{REPOSITORY}/releases?per_page=1")
            }),
            downloads: var("PANE_UPDATE_DOWNLOADS")
                .unwrap_or_else(|| format!("https://github.com/{REPOSITORY}/releases/download")),
            broker_downloads: var("PANE_UPDATE_BROKER_DOWNLOADS"),
        }
    }
}

fn agent() -> ureq::Agent {
    ureq::Agent::config_builder()
        .timeout_global(Some(TIMEOUT))
        .user_agent("pane-update")
        .build()
        .into()
}

fn get_text(url: &str) -> Result<String, String> {
    agent()
        .get(url)
        .header("accept", "application/vnd.github+json")
        .call()
        .map_err(|e| format!("{url}: {e}"))?
        .body_mut()
        .read_to_string()
        .map_err(|e| format!("{url}: {e}"))
}

fn download(url: &str, to: &Path) -> Result<(), String> {
    let response = agent().get(url).call().map_err(|e| format!("{url}: {e}"))?;
    let mut reader = response.into_body().into_reader();
    let mut file = fs::File::create(to).map_err(|e| format!("{}: {e}", to.display()))?;
    std::io::copy(&mut reader, &mut file).map_err(|e| format!("{url}: {e}"))?;
    file.flush().map_err(|e| format!("{}: {e}", to.display()))
}

//! Which accounts the person has taken out of the pool: `pool.toml` in the
//! gateway's data directory, `excluded = ["claude-work"]`. Every account is
//! in its pool unless named here -- the pool of a model being every account
//! whose catalogue serves it, in configuration order.
//!
//! **Read live.** A serving gateway asks [`PoolState::excluded`] per
//! request; the file is re-read only when its modification time changes, so
//! a toggle in Pane takes effect on the next request without a restart.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::SystemTime;

use anyhow::{Context as _, Result};

const FILE: &str = "pool.toml";

/// The exclusion list, cached by modification time.
pub struct PoolState {
    path: PathBuf,
    cache: Mutex<Option<(Option<(SystemTime, u64)>, BTreeSet<String>)>>,
}

impl PoolState {
    #[must_use]
    pub fn at(data_dir: &Path) -> Self {
        Self {
            path: data_dir.join(FILE),
            cache: Mutex::new(None),
        }
    }

    /// Whether `account` has been taken out of its pool.
    #[must_use]
    pub fn excluded(&self, account: &str) -> bool {
        self.excluded_set().contains(account)
    }

    /// Every excluded account, as the file says now.
    #[must_use]
    pub fn excluded_set(&self) -> BTreeSet<String> {
        let modified = std::fs::metadata(&self.path)
            .ok()
            .and_then(|m| Some((m.modified().ok()?, m.len())));
        let Ok(mut cache) = self.cache.lock() else {
            return read(&self.path);
        };
        if let Some((at, set)) = cache.as_ref()
            && *at == modified
        {
            return set.clone();
        }
        let set = read(&self.path);
        *cache = Some((modified, set.clone()));
        set
    }

    /// Takes `account` into its pool, or out of it.
    pub fn set(&self, account: &str, included: bool) -> Result<()> {
        let mut set = read(&self.path);
        if included {
            set.remove(account);
        } else {
            set.insert(account.to_string());
        }
        let list = set
            .iter()
            .map(|name| format!("{name:?}"))
            .collect::<Vec<_>>()
            .join(", ");
        let text = format!(
            "# Accounts taken out of their pool; edited by `inference-gateway subscriptions pool`.\nexcluded = [{list}]\n"
        );
        let temporary = self
            .path
            .with_extension(format!("toml.{}", std::process::id()));
        std::fs::write(&temporary, text)
            .with_context(|| format!("could not write {}", temporary.display()))?;
        std::fs::rename(&temporary, &self.path)
            .with_context(|| format!("could not write {}", self.path.display()))
    }
}

fn read(path: &Path) -> BTreeSet<String> {
    let Ok(text) = std::fs::read_to_string(path) else {
        return BTreeSet::new();
    };
    toml::from_str::<toml::Table>(&text)
        .ok()
        .and_then(|table| table.get("excluded").cloned())
        .and_then(|value| value.as_array().cloned())
        .map(|names| {
            names
                .iter()
                .filter_map(|name| name.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn an_account_leaves_and_rejoins_its_pool_and_a_reader_sees_it_live() {
        let dir = tempfile::tempdir().unwrap();
        let writer = PoolState::at(dir.path());
        let reader = PoolState::at(dir.path());
        assert!(!reader.excluded("claude-work"));
        writer.set("claude-work", false).unwrap();
        // A modification time can be coarse; a second write in the same
        // tick must still be seen, so the reader here is a fresh one.
        assert!(PoolState::at(dir.path()).excluded("claude-work"));
        assert!(!PoolState::at(dir.path()).excluded("claude-max"));
        writer.set("claude-work", true).unwrap();
        assert!(!PoolState::at(dir.path()).excluded("claude-work"));
    }
}

//! What each subscription has used of its limits, as the gateway reads it
//! from the provider (`inference-gateway subscriptions usage --json`): the
//! `/usage` panel, and one line at session start for a window that is
//! nearly spent. Figures are the provider's; a window it does not report is
//! not shown, and an account it would not answer for says why.

use serde::Deserialize;

use super::Session;
use crate::tui::{self, Panel};

/// A window at or above this share used is said at session start.
pub(super) const WARN_AT_PERCENT: f64 = 80.0;
const BAR_WIDTH: usize = 20;

#[derive(Debug, Deserialize)]
pub(super) struct Usage {
    #[serde(default)]
    pub accounts: Vec<AccountUsage>,
}

#[derive(Debug, Deserialize)]
pub(super) struct AccountUsage {
    pub account: String,
    pub plan: Option<String>,
    pub email: Option<String>,
    #[serde(default)]
    pub windows: Vec<Window>,
    #[serde(default)]
    pub limited: bool,
    pub error: Option<String>,
}

#[derive(Debug, Deserialize)]
pub(super) struct Window {
    pub name: String,
    pub used_percent: f64,
    pub resets_at: Option<String>,
}

/// The gateway's reading, or `None` when it could not be run.
pub(super) fn read(session: &Session<'_>) -> Option<Usage> {
    read_from(session.gateway)
}

fn read_from(gateway: &crate::gateway::Gateway) -> Option<Usage> {
    let bytes = gateway.run(&["subscriptions", "usage", "--json"], None)?;
    let usage: Usage = serde_json::from_slice(&bytes).ok()?;
    if let Ok(mut latest) = LATEST.lock() {
        *latest = Some(
            usage
                .accounts
                .iter()
                .map(|a| (a.account.clone(), summary(a)))
                .collect(),
        );
    }
    Some(usage)
}

/// The last reading's one-line summary per account, for the model picker:
/// the picker never waits on the providers, it shows what was last read.
static LATEST: std::sync::Mutex<Option<Vec<(String, String)>>> = std::sync::Mutex::new(None);

/// `Max 20x · 5h 4% · week 16%`, from the last reading, when there was one.
pub(super) fn latest_summary(account: &str) -> Option<String> {
    let latest = LATEST.lock().ok()?;
    let lines: Vec<&str> = latest
        .as_ref()?
        .iter()
        .filter(|(name, _)| name == account)
        .map(|(_, line)| line.as_str())
        .collect();
    (!lines.is_empty()).then(|| lines.join(" | "))
}

fn summary(account: &AccountUsage) -> String {
    let mut parts: Vec<String> = account.plan.iter().cloned().collect();
    if let Some(error) = &account.error {
        parts.push(error.clone());
    }
    parts.extend(
        account
            .windows
            .iter()
            .map(|w| format!("{} {:.0}%", w.name, w.used_percent)),
    );
    parts.join(" · ")
}

/// Warnings the start-of-session check left, shown at the next task's end.
static WARNINGS: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());

/// Reads usage once, on its own thread (two provider round trips must not
/// hold the first prompt), and leaves a line for each nearly-spent window.
pub(super) fn check_in_background(gateway: &crate::gateway::Gateway) {
    let gateway = gateway.clone();
    std::thread::spawn(move || {
        let Some(usage) = read_from(&gateway) else {
            return;
        };
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| i64::try_from(d.as_secs()).unwrap_or(0));
        if let Ok(mut held) = WARNINGS.lock() {
            held.extend(warnings(&usage, now));
        }
    });
}

/// The warnings left so far, taken once.
pub(super) fn take_warnings() -> Vec<String> {
    WARNINGS
        .lock()
        .map(|mut held| std::mem::take(&mut *held))
        .unwrap_or_default()
}

/// `/usage`: every subscription with a bar per window.
pub(super) fn panel(usage: Option<&Usage>, now_unix: i64) -> Panel {
    let Some(usage) = usage else {
        return Panel::text(
            "Usage",
            "The gateway could not be asked for subscription usage.".to_string(),
        );
    };
    if usage.accounts.is_empty() {
        return Panel::text(
            "Usage",
            "No subscription account is configured; /login connects one.".to_string(),
        );
    }
    let mut rows = Vec::new();
    for account in &usage.accounts {
        let who = [account.plan.as_deref(), account.email.as_deref()]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join(" · ");
        rows.push(tui::PanelRow {
            text: if who.is_empty() {
                account.account.clone()
            } else {
                format!("{} — {who}", account.account)
            },
            command: None,
        });
        if let Some(error) = &account.error {
            rows.push(tui::PanelRow {
                text: format!("  {error}"),
                command: None,
            });
        }
        for window in &account.windows {
            rows.push(tui::PanelRow {
                text: window_line(window, now_unix),
                command: None,
            });
        }
        if account.limited {
            rows.push(tui::PanelRow {
                text: "  a limit is reached now".to_string(),
                command: None,
            });
        }
    }
    Panel::rows("Usage", rows)
}

/// `  week   ████████████████░░░░  84%  resets in 2d 22h`
